def fibonacci_at(n):
    # Base cases
    if n == 0:
        return 0
    if n == 1:
        return 1

    # For n >= 2, compute using iteration
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b

    return b
```

